  "risk": {
    "level": "high",
    "touches": ["wallet", "wallet_storage", "rpc_api"],
    "why": "Flaws in keypath parsing or descriptor expansion could result in deriving incorrect addresses or failing to parse existing wallet records, leading to inaccessible funds or corrupted wallet databases."
  }
}
